input.newString:
// Floating waypoints and ride collectibles
const markers=[];for(let i=0;i<7;i++){const x=-500+i*155,z=roadZ(x)+(i%2?1:-1)*15;const ring=new THREE.Mesh(new THREE.TorusGeometry(1.3,.12,8,24),mat(0xffd26f,.25,.3));ring.position.set(x,2.8,z);ring.rotation.x=Math.PI/2;scene.add(ring);const orb=new THREE.Mesh(new THREE.SphereGeometry(.35,12,8),mat(0xfff0b0,.2,.2));orb.position.set(x,2.8,z);scene.add(orb);markers.push({x,z,ring,orb,got:false})}
const keys={};let playing=false,velocity=0,steer=0,heading=0,score=0,toastTimer=0;const player={x:-720,z:roadZ(-720)-1};bike.position.set(player.x,0,player.z);const toastEl=document.querySelector('#toast');function toast(msg){toastEl.textContent=msg;toastEl.classList.add('show');toastTimer=2.5}
function startRide(){playing=true;document.querySelector('#start').classList.add('hidden');toast('The village is waking up · enjoy the ride');bike.position.set(player.x,0,player.z)}document.querySelector('#startbtn').addEventListener('click',startRide);
window.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(key))e.preventDefault();keys[key==='w'||key==='arrowup'?'up':key==='s'||key==='arrowdown'?'brake':key==='a'||key==='arrowleft'?'left':key==='d'||key==='arrowright'?'right':key===' '?'brake':key]=true;if(key==='enter'&&!playing)startRide()});window.addEventListener('keyup',e=>{const key=e.key.toLowerCase();keys[key==='w'||key==='arrowup'?'up':key==='s'||key==='arrowdown'?'brake':key==='a'||key==='arrowleft'?'left':key==='d'||key==='arrowright'?'right':key===' '?'brake':key]=false});document.querySelectorAll('.ctrl').forEach(b=>{const k=b.dataset.key;const on=e=>{e.preventDefault();keys[k]=true;b.classList.add('down')},off=e=>{e.preventDefault();keys[k]=false;b.classList.remove('down')};b.addEventListener('pointerdown',on);['pointerup','pointercancel','pointerleave'].forEach(ev=>b.addEventListener(ev,off))});
// Minimap drawing
const mapCanvas=document.querySelector('#minimap'),mapCtx=mapCanvas.getContext('2d');function drawMap(){const c=mapCtx;c.clearRect(0,0,228,228);c.fillStyle='#153e3d';c.fillRect(0,0,228,228);c.fillStyle='#346b67';c.beginPath();c.ellipse(174,35,70,95,-.2,0,Math.PI*2);c.fill();c.strokeStyle='#d2c49b';c.lineWidth=7;c.beginPath();for(let x=0;x<=220;x++){const wx=player.x-300+x*2.7,z=roadZ(wx);const px=x,py=114+(z-player.z)*.65;if(!x)c.moveTo(px,py);else c.lineTo(px,py)}c.stroke();for(const m of markers)if(!m.got){const px=114+(m.x-player.x)*.34,py=114+(m.z-player.z)*.34;if(px>0&&px<228&&py>0&&py<228){c.fillStyle='#ffd16a';c.beginPath();c.arc(px,py,3.5,0,Math.PI*2);c.fill()}}c.fillStyle='#fff';c.beginPath();c.arc(114,114,5,0,Math.PI*2);c.fill();c.strokeStyle='#ffc95c';c.lineWidth=2;c.stroke()}
let last=performance.now();function animate(now){requestAnimationFrame(animate);const dt=Math.min(.04,(now-last)/1000);last=now;const t=now*.001;if(playing){const ped=!!keys.up,brake=!!keys.brake;velocity+=ped?7.2*dt:-3.3*dt;if(brake)velocity-=13*dt;velocity=THREE.MathUtils.clamp(velocity,0,20);const steerInput=(keys.left?-1:0)+(keys.right?1:0);steer=THREE.MathUtils.damp(steer,steerInput,.11,dt);heading+=steer*velocity*.0035*dt;player.x+=Math.sin(heading)*velocity*dt;player.z+=Math.cos(heading)*velocity*dt;const roadCenter=roadZ(player.x);const offroad=Math.abs(player.z-roadCenter)>9;if(offroad)velocity=Math.max(0,velocity-5*dt);bike.position.set(player.x,.03,player.z);bike.rotation.y=heading;bike.rotation.z=-steer*velocity*.007;for(const m of markers){m.ring.rotation.z=t*.75;m.orb.position.y=2.8+Math.sin(t*2+m.x)*.18;if(!m.got&&Math.hypot(player.x-m.x,player.z-m.z)<3.6){m.got=true;m.ring.visible=false;m.orb.visible=false;score++;toast(score===7?'All seven moments found · what a ride!':'Postcard found · '+score+' / 7')}}document.querySelector('#speed').innerHTML=Math.round(velocity*3.6)+'<span> km/h</span>';document.querySelector('#mission').textContent=score===7?'Ride complete · keep exploring':`Find the old tea stop · ${score}/7`;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)toastEl.classList.remove('show')}}
 // Keep the traffic moving on the left lane; all vehicles follow the village road.
 for(const v of traffic){v.x+=v.direction*v.speed*dt;if(v.x>860)v.x=-860;if(v.x< -860)v.x=860;const z=roadZ(v.x)+v.side;v.g.position.set(v.x,0,z);v.g.rotation.y=v.direction>0?Math.PI/2:-Math.PI/2;}
 const target=new THREE.Vector3(player.x-Math.sin(heading)*11,7.2,player.z-Math.cos(heading)*11);camera.position.lerp(target,1-Math.exp(-3.2*dt));camera.lookAt(player.x,1.3,player.z+Math.cos(heading)*5);sun.position.set(player.x-90,140,player.z-80);sun.target.position.set(player.x,0,player.z);sun.target.updateMatrixWorld();drawMap();renderer.render(scene,camera)}requestAnimationFrame(animate);
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});
</script></body></html>

